import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1173, own='cte_96.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 749 Firefighter II ----
H("749.d.1.A",3,"A Firefighter II student practices calling for backup on the radio and logging the call on a computer. This is applying:","protocols for managing emergencies using radio equipment and computers",["avoiding technology","ignoring protocols","guessing"],"Radio and computers support emergency management.")
H("749.d.1.A",4,"Which tool helps a dispatcher record unit status during a large emergency?","a computer-aided dispatch system",["a paper airplane","a cookbook","a calendar poster"],"CAD tracks units and calls.")
H("749.d.1.B",3,"A fire officer builds a spreadsheet of hydrant flow tests and writes a summary report in a word processor. This demonstrates:","word-processing and spreadsheet use in fire management",["avoiding software","hiding data","unrelated tasks"],"Software supports records and analysis.")
H("749.d.1.B",4,"A fire chief wants to compare response times over a year. The best software to organize the numbers is a:","spreadsheet",["slide show only","game","photo editor"],"Spreadsheets organize and calculate data.")
H("749.d.2.A",3,"Engine company members learn the steps to follow when an alarm comes in for a kitchen fire. This is identifying:","response procedures to emergency incidents",["unrelated chores","only paperwork","only meals"],"Procedures guide response.")
H("749.d.2.A",4,"A written response procedure for emergency incidents helps crews by:","providing consistent steps to follow under stress",["adding confusion","delaying response","replacing training"],"Procedures reduce errors.")
H("749.d.2.B",3,"In a training drill, a crew responds to a simulated apartment fire, following their written steps. This is:","applying response procedures in a simulation",["ignoring steps","skipping practice","random action"],"Simulations rehearse procedures.")
H("749.d.2.B",4,"The main value of simulated emergency drills is that they:","let crews practice procedures safely before real calls",["cause injury","replace real calls","remove procedures"],"Practice builds skill.")
H("749.d.3.A",3,"A stove grease fire, a paper fire and an energized panel fire fall into different:","classes of fire for portable extinguisher selection",["vehicle classes","school classes","rank classes"],"Fire classes determine the right agent.")
H("749.d.3.A",4,"A fire involving ordinary combustibles such as wood and paper is a:","Class A fire",["Class B fire","Class C fire","Class K fire"],"Class A = ordinary combustibles.")
H("749.d.3.B",3,"A firefighter selects a carbon dioxide extinguisher for a fire in an energized computer panel. This shows:","choosing the appropriate extinguisher for each fire class",["random choice","using water","avoiding extinguishers"],"CO2 is non-conductive.")
H("749.d.3.B",4,"Which extinguisher is the correct choice for a flammable liquid fire?","a Class B-rated extinguisher",["a Class A water can","a garden hose","a broom"],"Class B covers flammable liquids.")
H("749.d.3.C",3,"A technician notes an extinguisher's agent, range, discharge time and pressure gauge. These are its:","characteristics and operations",["colors only","brand only","shape only"],"Characteristics inform use.")
H("749.d.3.C",4,"Before using an extinguisher, a firefighter checks the gauge to be sure the:","pressure is in the operable range",["handle is red","label is new","pin is rusty"],"A full charge is needed.")
H("749.d.3.D",3,"A trainee pulls the pin, aims at the base of the fire, squeezes the handle and sweeps side to side. This is the:","PASS method for operating an extinguisher",["fire triangle","hose lay","ladder carry"],"Pull, Aim, Squeeze, Sweep.")
H("749.d.3.D",4,"In the PASS method, the 'Aim' step means to point the nozzle at:","the base of the fire",["the top of the flames","the ceiling","the wall"],"Aim low at the base.")
H("749.d.4.A",3,"Ground ladders may be made of aluminum, fiberglass or wood. These are the:","materials used in ladder construction",["colors of ladders","brands of ladders","sizes of hoses"],"Each material has pros and cons.")
H("749.d.4.A",4,"Why are fiberglass ladders used near power lines?","Fiberglass does not conduct electricity like metal does",["It is heavier","It is cheaper","It is invisible"],"Non-conductive.")
H("749.d.4.B",3,"Before a ladder is placed back on the truck, a firefighter checks rungs, rails, pulleys and heat-sensor labels. This is:","inspection and maintenance of ground ladders",["painting","ignoring damage","tossing it"],"Inspection prevents failures.")
H("749.d.4.B",4,"A ladder with a cracked rung should be:","taken out of service until repaired",["used with caution","painted over","used for light work"],"Damaged ladders are unsafe.")
H("749.d.4.C",3,"The weight a ladder can safely carry is called its:","load capacity",["rung color","length","age"],"Load capacity is a safety rating.")
H("749.d.4.C",4,"Exceeding a ground ladder's load capacity can cause:","ladder failure and injury",["a faster climb","a lighter ladder","a quieter climb"],"Overloading is dangerous.")
H("749.d.4.D",3,"To reach a third-floor window, a crew picks a ladder long enough to extend a few rungs above the sill. This is:","selecting a ladder for a given task",["ignoring size","guessing","random choice"],"Match the ladder to the job.")
H("749.d.4.D",4,"When selecting a ladder to reach a roof edge, firefighters should consider:","its length, load rating and the angle needed",["its color","its age only","its brand only"],"Select for length and safety.")
H("749.d.4.E",3,"Two firefighters carry a ladder to the wall, lift it and place its base at the correct distance. This is:","raising and positioning a ground ladder",["dropping a ladder","avoiding practice","ignoring safety"],"Safe raising needs teamwork.")
H("749.d.4.E",4,"A common rule for ladder angle is that the base should be placed:","about one-quarter of the working height from the wall",["flush against the wall","far from the wall","upside down"],"A 4-to-1 rule gives a safe angle.")
H("749.d.4.F",3,"After placing a ladder, a firefighter foots the ladder or ties it off so it won't slip. This is:","securing a ladder",["dropping a ladder","ignoring a ladder","moving a ladder"],"A secured ladder is stable.")
H("749.d.4.F",4,"The purpose of securing a ladder before climbing is to:","prevent slipping or shifting",["make it heavier","make it shorter","make it louder"],"Stability prevents falls.")
H("749.d.4.G",3,"A firefighter carries a pike pole up a ladder using one hand and keeping three points of contact. This is:","proper climbing technique while transporting tools",["unsafe climbing","skipping steps","racing"],"Tools must be carried safely.")
H("749.d.4.G",4,"While climbing a ladder with a tool, a firefighter should:","keep a hand and firm footing on the ladder at all times",["carry with both hands","slide down","jump off"],"Stay in contact with the ladder.")
H("749.d.4.H",3,"On a pitched roof, a crew uses a ladder with hooks that anchors over the ridge to give footing. This is:","deploying a roof ladder",["dropping a ladder","avoiding roofs","running a hose"],"Roof ladders provide stable footing.")
H("749.d.4.H",4,"A roof ladder's hooks are placed over the:","ridge of the roof",["window","gutter","chimney cap"],"Hooks anchor at the ridge.")
H("749.d.5.A",3,"Fire hose is built with a jacket and liner, with metal or plastic couplings at each end. This describes:","the use and construction of fire hoses and couplings",["ladders","helmets","extinguishers"],"Hose construction determines use.")
H("749.d.5.A",4,"A coupling on a fire hose allows the hose to:","connect to other hose, nozzles or hydrants",["change color","stretch forever","heat up"],"Couplings join equipment.")
H("749.d.5.B",3,"An engine carries larger-diameter supply hose for long water lines and smaller attack hose for fire attack. This explains:","the application of each size and type of hose",["decorative hose","empty hose","random hose"],"Hose size matches the task.")
H("749.d.5.B",4,"A supply line that carries water from a hydrant to the pumper is usually:","large-diameter hose",["tiny garden hose","booster only","electric cable"],"Supply lines need big flow.")
H("749.d.5.C",3,"A firefighter aligns two Storz couplings and twists them to lock. This shows:","a method of connecting fire hose couplings",["cutting hose","drying hose","burning hose"],"Couplings connect in set ways.")
H("749.d.5.C",4,"Before connecting hose couplings, firefighters check that the gaskets are:","present and clean",["missing","dirty","torn"],"Gaskets prevent leaks.")
H("749.d.5.D",3,"One firefighter and then two firefighters practice joining, breaking apart and rolling a section of hose. This is:","one- and two-person methods for connecting, dismantling and rolling hose",["tangling hose","ignoring hose","tossing hose"],"Hose handling is taught with partners.")
H("749.d.5.D",4,"When rolling hose after a fire, firefighters should first:","drain and clean it so it can be rolled properly",["roll it wet and dirty","stomp it","leave it"],"Preparation protects hose.")
H("749.d.5.E",3,"A crew pulls an empty hose line to the door and then charges it with water as they advance. This is:","advancing dry and charged attack lines",["retreating","ignoring fire","running away"],"Advancing lines is a core skill.")
H("749.d.5.E",4,"A charged hose line compared with an empty one is:","heavier and more rigid",["lighter and flexible","weightless","invisible"],"Water adds weight.")
H("749.d.5.F",3,"Hose loads can be finished in several ways such as a horseshoe or a flat load. These are:","hose load finishes",["fire classes","ladder types","helmet styles"],"Finishes help pull and advance hose.")
H("749.d.5.F",4,"A hose load finish is designed so that hose will:","deploy smoothly and without tangles",["tangle","tie in knots","stay in the bed"],"Good loads deploy cleanly.")
H("749.d.5.G",3,"A hose bursts at a fire, so a crew shuts off the water, replaces the section and restarts flow. This is:","extending and replacing damaged hose",["ignoring the problem","dropping the line","running away"],"Damaged sections are replaced.")
H("749.d.5.G",4,"Before replacing a damaged hose section, firefighters should:","shut down the water flow to that line",["increase pressure","keep flow on","cut the line"],"Safety before repair.")
H("749.d.5.H",3,"After a fire, crews wash hose with mild soap and hang it to dry to prevent mildew. These are:","methods of washing and drying fire hose",["methods of burning","methods of dropping","methods of cutting"],"Hose care extends its life.")
H("749.d.5.H",4,"Why must a fire hose be dried before storage?","Moisture can cause mildew and weaken the jacket",["Dry hose is heavier","Water helps it last","It is a tradition"],"Dry storage prevents damage.")
H("749.d.6.A",3,"A straight stream, a fog stream and a solid stream behave differently on a fire. These are:","characteristics of fire streams",["colors of hose","brands of nozzle","types of ladders"],"Streams differ by pattern and reach.")
H("749.d.6.A",4,"A straight stream is best used when a firefighter needs:","reach and penetration",["a wide curtain","less water","no pressure"],"Straight streams reach far.")
H("749.d.6.B",3,"A nozzle label lists its flow in gallons per minute and the pressure it needs. This helps identify:","the type, design, operation and required pressure of a nozzle",["the color","the weight only","the brand only"],"Specs guide use.")
H("749.d.6.B",4,"A smooth-bore nozzle typically provides:","a solid stream with good reach",["a fog only","a mist","no water"],"Smooth bore gives a solid stream.")
H("749.d.6.C",3,"A firefighter uses a gated wye, a reducer and a nozzle to split one line into two. This is:","proper use of nozzles, hose appliances, valves and adapters",["misusing tools","avoiding appliances","guessing"],"Appliances manage water flow.")
H("749.d.6.C",4,"A wye appliance lets a crew:","divide one hose line into two",["combine two lines to one","stop all flow","burn hose"],"Wyes split lines.")
H("749.d.6.D",3,"Pistol grips, bails, tips and shutoff valves are all components of a:","fire nozzle",["ladder","helmet","hydrant"],"Nozzles have several parts.")
H("749.d.6.D",4,"A nozzle's shutoff allows the firefighter to:","start and stop the water flow",["change the color","raise the pump","lock the door"],"Shutoffs control flow.")
H("749.d.6.E",3,"Terms such as friction loss, flow rate and pressure are:","terms related to fire service hydraulics",["food terms","art terms","sports terms"],"Hydraulics explains water movement.")
H("749.d.6.E",4,"Friction loss in a hose line refers to:","the drop in pressure caused by water moving through the hose",["the gain of pressure","the speed of the truck","the height of the ladder"],"Friction reduces pressure.")
H("749.d.7.A",3,"A hydrant is opened fully for flow and the water is shut off slowly, never abruptly. This describes:","the proper operation of fire hydrants",["random operation","a hydrant failure","a hose test"],"Slow operation prevents water hammer.")
H("749.d.7.A",4,"Opening a hydrant slowly and fully helps avoid:","damage from surges in the water system",["loud noise only","cold water","low flow"],"Gradual operation protects equipment.")
H("749.d.7.B",3,"A hydrant painted with a certain cap color tells firefighters its flow capacity. This is the:","NFPA hydrant color code",["traffic code","paint code","uniform code"],"Colors indicate flow rates.")
H("749.d.7.B",4,"Under the NFPA hydrant color code, a hydrant with a red cap indicates:","the lowest flow capacity",["the highest flow","no water","out of service only"],"Red is under 500 gpm.")
H("749.d.7.C",3,"A firefighter connects a large hose from the hydrant outlet to the pumper intake. This is making a:","hydrant-to-pumper connection",["tank refill","roof ladder lift","nozzle test"],"The connection supplies water.")
H("749.d.7.C",4,"Before connecting a hydrant, firefighters should:","flush the hydrant to clear debris",["close the cap","ignore it","paint it"],"Flushing prevents debris in the pump.")
H("749.d.7.D",3,"A poorly connected supply line may leak, whip or burst when charged. These are:","hazards of an improper hydrant-to-pumper connection",["benefits","routine events","design features"],"Improper connections are dangerous.")
H("749.d.7.D",4,"A loose coupling on a charged hydrant line can result in:","injury to crew and loss of water supply",["extra water","cooler water","better pressure"],"Loose connections are hazardous.")
H("749.d.7.E",3,"Where there are no hydrants, firefighters use tankers, portable tanks and pumps to supply water. This describes:","apparatus and appliances to provide water in rural areas",["urban supply","no supply","random supply"],"Rural water supply uses shuttles and tanks.")
H("749.d.7.E",4,"In a rural area without hydrants, firefighters might create a water supply using:","a tanker shuttle with portable drop tanks",["only a garden hose","a sponge","an empty barrel"],"Tankers and drop tanks supply water.")
H("749.d.8.A",3,"After a house fire, crews remove burned materials and wet debris to prevent rekindling. This is:","handling debris from fires",["ignoring cleanup","starting a fire","spreading debris"],"Overhaul removes hidden fire sources.")
H("749.d.8.A",4,"Firefighters handle debris from a chemical fire differently because it may:","contain hazardous residues",["be harmless","be lighter","be scented"],"Chemical debris needs special handling.")
H("749.d.8.B",3,"An officer notes burn patterns, witnesses' statements and the first area of ignition to help investigators. These are:","duties for gathering information about the cause of a fire",["ignoring evidence","guessing","closing a case"],"Early notes help cause determination.")
H("749.d.8.B",4,"Why must firefighters preserve the area of origin after a fire?","It may hold evidence needed to determine the cause",["It is a rule for decoration","It saves time","It improves cleanup"],"Preserve evidence.")
H("749.d.8.C",3,"After the fire is out, firefighters secure the building, board openings and protect the property. This is:","restoration of the premises after a fire",["abandoning the building","starting another fire","stealing property"],"Restoration secures and protects.")
H("749.d.8.C",4,"Securing a damaged building after a fire helps prevent:","theft, entry by others and further damage",["loud noise only","traffic","pets"],"Securing protects property.")
H("749.d.8.D",3,"A firefighter stays at the fire scene watching for rekindling and guarding the property. These are duties of:","fire and security surveillance during and after a fire",["leaving early","ignoring the scene","sleeping"],"Surveillance prevents rekindles.")
H("749.d.8.D",4,"A fire watch after a large fire is kept to:","catch hidden hot spots that might reignite",["avoid training","increase noise","deliver supplies"],"Rekindles can occur.")

# ---- 750 Law Enforcement I ----
H("750.d.1.A",3,"In a police academy lesson, a cadet defines 'reasonable force' and cites the law that lets an officer use force when making an arrest. This is learning:","use-of-force terminology and legal authority",["parking rules","uniform styles","radio brands"],"Officers need to know terms and legal authority.")
H("750.d.1.A",4,"Legal authority for an officer to use force generally comes from:","state law and constitutional limits",["personal choice","a coin flip","a supervisor's mood"],"Law defines when force is allowed.")
H("750.d.1.B",3,"An officer weighs the suspect's actions, the threat level and the available options before deciding whether to use force during an arrest. These are:","deciding factors for use of force",["irrelevant details","jokes","guesses"],"Force depends on the situation.")
H("750.d.1.B",4,"Which factor most directly affects the amount of force justified in an arrest?","how much the suspect resists or threatens the officer or others",["the officer's mood","the weather","the car's color"],"Force must be proportional to resistance and threat.")
H("750.d.1.C",3,"A lone officer approaches a dark building where a burglary alarm sounded. Such situations are considered:","high-risk circumstances for officers",["safe routine tasks","paperwork","holiday events"],"Unknown threats raise risk.")
H("750.d.1.C",4,"Which situation is generally a high risk for officers?","a felony vehicle stop",["a routine desk shift","a school assembly","a library tour"],"Felony stops can involve armed suspects.")
H("750.d.1.D",3,"A trainer shows that talking, a control hold, a baton and a firearm are different options on a force scale. This raises awareness of:","force options and alternatives",["only deadly force","no options","one tool for all situations"],"Officers have multiple options.")
H("750.d.1.D",4,"Considering alternatives to force first is useful because it:","can resolve situations with less risk of injury",["wastes time","ends law enforcement","removes training"],"De-escalation reduces harm.")
H("750.d.1.E",3,"Peace officers may use verbal commands, soft restraints, tools such as batons or conducted energy weapons, or firearms as a last resort. These are:","force options available to peace officers",["office tasks","hobbies","fashion choices"],"Several options exist along a continuum.")
H("750.d.1.E",4,"The use of lethal force by an officer is generally allowed only when:","there is a serious threat of death or serious injury",["a suspect is rude","a person runs from a minor ticket","the officer is annoyed"],"Deadly force is limited to grave threats.")
H("750.d.1.F",3,"A patrol officer scans for weapons, watches hands and keeps a safe distance during a contact. This shows:","recognizing and controlling elements in every encounter",["ignoring surroundings","casual chatting only","looking away"],"Control of the encounter protects safety.")
H("750.d.1.F",4,"Maintaining a position of advantage and awareness during a stop helps an officer to:","control the encounter and respond to changes",["avoid reports","ignore the suspect","hide evidence"],"Positioning improves safety.")
H("750.d.2.A",3,"A cadet learns what 'probable cause', 'warrant' and 'arraignment' mean before studying case law. This is relating:","technical concepts and vocabulary associated with law enforcement",["recipes","sports terms","music"],"Terminology supports learning.")
H("750.d.2.A",4,"Which term describes a judge's written order authorizing police to search a place?","a search warrant",["a traffic cone","a report card","a badge"],"Warrants authorize searches.")
H("750.d.2.B",3,"Eye contact, crossed arms and nervous gestures give an officer clues about a person's feelings during an interview. This is interpreting:","facial expressions, gestures and body posture",["written grammar","only words","badge numbers"],"Non-verbal cues convey meaning.")
H("750.d.2.B",4,"A person who avoids eye contact and fidgets during questioning is showing:","nonverbal cues that may or may not indicate stress",["proof of guilt","proof of innocence","a legal fact"],"Cues require context and are not proof.")
H("750.d.2.C",3,"A witness whose voice rises and quickens when describing a robbery is conveying emotion through:","pitch, tone and word choice",["only spelling","only grammar","only badges"],"Vocal delivery carries meaning.")
H("750.d.2.C",4,"Which is an example of voice quality an officer would interpret?","a trembling, high-pitched voice",["a typed message","a printed report","a map"],"Voice cues show emotion.")
H("750.d.2.D",3,"An officer greets residents in their own language and respects local customs when taking a report. This shows:","recognizing diversity in culture",["ignoring differences","stereotyping","avoiding the public"],"Cultural awareness builds trust.")
H("750.d.2.D",4,"Recognizing cultural diversity helps officers to:","communicate respectfully and avoid misunderstandings",["avoid training","treat all situations the same without thought","ignore concerns"],"Understanding supports effective communication.")
H("750.d.2.E",3,"During a briefing, a cadet makes eye contact, nods and later summarizes what the sergeant said. This is:","employing active listening skills",["ignoring the briefing","interrupting","sleeping"],"Summarizing shows understanding.")
H("750.d.2.E",4,"Which action is an example of active listening?","Paraphrasing what was said to confirm understanding",["Checking a phone","Talking over others","Leaving"],"Paraphrasing confirms understanding.")
H("750.d.2.F",3,"At a shift meeting, an officer shares an idea about neighborhood patrols and listens to others' ideas. This is:","contributing to group discussions and meetings",["avoiding meetings","dominating","ignoring ideas"],"Participation improves teamwork.")
H("750.d.2.F",4,"A constructive way to contribute in a meeting is to:","offer relevant ideas and respect others' views",["interrupt often","stay silent always","criticize without reason"],"Good participation is respectful.")
H("750.d.3.A",3,"A cadet fills in the date, location, vehicles, drivers and diagram for a two-car collision. This is producing a:","crash report",["traffic ticket","arrest warrant","parking permit"],"Crash reports record facts.")
H("750.d.3.A",4,"An accurate crash report should include:","time, place, vehicles, people involved and a diagram",["only the weather","only opinions","only gossip"],"Reports need complete factual detail.")
H("750.d.3.B",3,"After a crash, an officer cites the Texas Transportation Code on failing to yield right of way. This is applying:","laws associated with accident investigation",["avoiding the law","guessing","skipping the report"],"Investigators apply traffic law.")
H("750.d.3.B",4,"Under Texas law, drivers involved in a crash that causes injury must:","stop and give information and aid",["leave quickly","hide","ignore the injured"],"Duty upon involvement.")
H("750.d.3.C",3,"Officers learn to park to protect the scene, turn on lights and call for help before starting an investigation. This researches:","procedures for responding to an accident scene and maintaining control",["avoiding the scene","leaving early","blocking help"],"Scene control protects people.")
H("750.d.3.C",4,"The first priority at an accident scene is usually to:","ensure safety and get help to anyone injured",["measure skid marks","write tickets","move all cars"],"Life safety first.")
H("750.d.3.D",3,"An officer uses cones, flares and hand signals to guide cars around a wreck. This is:","maintaining traffic control at an accident scene",["creating traffic jams","ignoring drivers","blocking the road at random"],"Traffic control protects responders.")
H("750.d.3.D",4,"Which action helps maintain traffic control at a crash?","Placing warning devices well before the scene",["Removing all signs","Standing in the lane","Turning off lights"],"Advance warning prevents secondary crashes.")
H("750.d.4.A",3,"The Constitution sets limits on police power, such as protecting people from unreasonable searches. This explains the Constitution's role in:","developing and implementing law enforcement policy",["no policy","only taxes","only school rules"],"Policies reflect constitutional limits.")
H("750.d.4.A",4,"Which part of the U.S. Constitution most directly protects people from unreasonable searches?","the Fourth Amendment",["the Second Amendment","the Third Amendment","the Twelfth Amendment"],"Fourth Amendment covers searches and seizures.")
H("750.d.4.B",3,"A cadet considers whether an officer should keep a gift left by a grateful resident. This is evaluating:","individual ethical behavior standards",["fashion","traffic rules","hobbies"],"Ethics guide conduct.")
H("750.d.4.B",4,"A standard of ethical behavior for officers includes:","honesty, fairness and respect for rights",["favoritism","bending rules","hiding errors"],"Ethical behavior is essential.")
H("750.d.4.C",3,"An agency's code of conduct and the law both forbid planting evidence because it violates citizens' rights. This is:","legal and ethical standards protecting constitutional rights",["optional advice","a rumor","a game"],"Law and ethics protect rights.")
H("750.d.4.C",4,"Why are legal and ethical standards important in policing?","They protect citizens' rights and public trust",["They add paperwork","They limit patrols","They end arrests"],"Rights and trust are the goal.")
H("750.d.4.D",3,"An officer attends neighborhood meetings, responds politely and explains actions to residents. These are strategies to:","enhance public trust",["reduce trust","avoid the public","limit transparency"],"Open communication builds trust.")
H("750.d.4.D",4,"Which action best enhances public trust in the police?","Being transparent, respectful and fair",["Avoiding questions","Using force often","Ignoring complaints"],"Fair treatment earns trust.")
H("750.d.4.E",3,"A law enforcement agency's mission statement says it protects lives, property and rights in a free society. This is its:","mission in protecting a democratic society",["menu","slogan for sports","fashion goal"],"Police protect democratic values.")
H("750.d.4.E",4,"The mission of law enforcement in a democracy includes:","enforcing the law while protecting individual rights",["ignoring rights","using unlimited power","avoiding the public"],"Rights and order go together.")
H("750.d.5.A",3,"A resident is protected from being searched without a warrant by the U.S. Constitution, the Texas Constitution and city rules. This shows:","protection by constitutional laws at local, state and federal levels",["no protection","one level only","rumors"],"Multiple layers of law protect citizens.")
H("750.d.5.A",4,"Which statement is true about constitutional protection of citizens?","Federal, state and local laws all place limits on police actions",["Only federal law applies","No laws apply to police","Only city law applies"],"Layered protections.")
H("750.d.5.B",3,"In Mapp v. Ohio, the Supreme Court held that evidence obtained through an illegal search cannot be used in state courts. This is the:","exclusionary rule applied to the states",["Miranda rule","speedy-trial rule","double jeopardy"],"Mapp extended the rule.")
H("750.d.5.B",4,"Terry v. Ohio allows an officer to briefly stop and pat down a person if the officer has:","reasonable suspicion that the person is armed and dangerous",["no reason","a hunch only","a dislike"],"Terry permits limited stop-and-frisk.")
H("750.d.5.C",3,"A city ordinance, a state statute and a federal law may all address the same behavior. This shows the:","similarities, differences and interactions of local, state and federal law",["conflict of rules only","absence of law","random rules"],"Laws overlap and interact.")
H("750.d.5.C",4,"If a local law conflicts with the U.S. Constitution, the:","Constitution controls",["local law controls","state law controls","the police chief decides"],"The Constitution is supreme law.")
H("750.d.5.D",3,"A case begins with an arrest, moves to a hearing, then a trial and perhaps an appeal. This illustrates:","the progression of a case through local, state and federal courts",["a random event","a traffic stop","a patrol shift"],"Cases proceed through stages.")
H("750.d.5.D",4,"A losing party who thinks a legal error occurred can:","appeal to a higher court",["start over without notice","ignore the ruling","call the arresting officer"],"Appeals review legal error.")
H("750.d.5.E",3,"A person sues a company for damages, while the state charges a person with burglary. These show:","differences between civil and criminal court systems",["no difference","weather patterns","sports leagues"],"Civil seeks remedies; criminal seeks punishment.")
H("750.d.5.E",4,"A key characteristic of criminal cases is that the government must prove guilt:","beyond a reasonable doubt",["by a hunch","by a rumor","by a simple majority of opinions"],"Higher standard in criminal cases.")
H("750.d.6.A",3,"An officer reads a suspect the Miranda warning before custodial questioning begins. This applies the:","constitutional rights against self-incrimination and to counsel",["traffic law","school rule","tax law"],"Miranda protects Fifth and Sixth Amendment rights.")
H("750.d.6.A",4,"Miranda warnings must be given before questioning when a person is:","in custody and subject to interrogation",["walking in public","asking for directions","paying a fee"],"Custody plus interrogation triggers Miranda.")
H("750.d.6.B",3,"When a juvenile is a suspect, Texas law adds steps such as taking the child before a magistrate for warnings. This explains:","additional requirements beyond Miranda for juvenile suspects",["fewer requirements","no requirements","adult rules only"],"Juveniles have extra protections.")
H("750.d.6.B",4,"Compared with adults, juvenile suspects in Texas receive:","extra procedural protections before a statement can be used",["fewer rights","no warnings","no counsel"],"Juvenile law adds safeguards.")
H("750.d.6.C",3,"A trainee practices an informal talk with a witness who is free to leave and a formal questioning of a suspect in custody. This demonstrates:","non-custodial and custodial interviews and interrogation",["only one kind of talk","avoiding talks","no technique"],"Custody changes the rules.")
H("750.d.6.C",4,"The main difference between a non-custodial and custodial interview is that in a custodial interview:","the person is not free to leave",["no one is present","no notes are taken","no law applies"],"Custody triggers rights.")
H("750.d.7.A",3,"The Texas Penal Code sorts crimes into classes such as felonies and misdemeanors with different punishments. This defines:","crime categories and their punishments",["no categories","only weather","only traffic"],"Categories set penalties.")
H("750.d.7.A",4,"In Texas, a Class C misdemeanor is punishable by:","a fine only",["life in prison","the death penalty","five years in jail"],"Class C is fine only.")
H("750.d.7.B",3,"To prove driving while intoxicated, the state must show the person was driving and was intoxicated. These are:","elements of a criminal act under Texas law",["unrelated facts","opinions","rumors"],"Elements are the parts of a crime.")
H("750.d.7.B",4,"Which is an element commonly required for a driving-while-intoxicated charge?","operating a motor vehicle in a public place while intoxicated",["owning a car","wearing a seat belt","paying a toll"],"Operating while intoxicated is an element.")
H("750.d.7.C",3,"Murder is wrong in itself, while speeding is wrong only because a law prohibits it. These examples show:","mala in se and mala prohibita",["civil and criminal","felony and bail","jury and judge"],"Mala in se = inherently wrong; mala prohibita = prohibited by law.")
H("750.d.7.C",4,"Which is an example of mala prohibita?","driving without a required license",["murder","robbery","assault"],"It is wrong because law prohibits it.")
H("750.d.7.D",3,"A person charged with assault claims they acted to protect themselves from an attack. This is a type of:","criminal defense (self-defense)",["confession","arrest","bail"],"Self-defense is a justification defense.")
H("750.d.7.D",4,"A defendant who proves they were not at the scene because they were elsewhere is using:","an alibi defense",["an insanity defense","a self-defense claim","a plea bargain"],"Alibi means elsewhere at the time.")
H("750.d.8.A",3,"A bill of rights for crime victims gives them the right to be informed and treated fairly in the justice process. This relates to:","the rights of victims of crimes and witnesses",["rights of suspects only","traffic rules","school rules"],"Victims have legal rights.")
H("750.d.8.A",4,"Under Texas law, a crime victim has the right to:","be treated with fairness and be informed about the case",["control the verdict","skip court always","hold the trial"],"Fairness and information are standard rights.")
H("750.d.8.B.i",3,"A burglary victim feels afraid in her home for months after the crime. This is an example of the:","psychological impact of crime on the victim",["economic gain","ignorable effect","trivial effect"],"Crime can cause lasting fear and stress.")
H("750.d.8.B.i",4,"Symptoms such as anxiety, sleeplessness and fear after a violent crime are examples of the:","psychological effects on victims",["economic benefits","legal rewards","social perks"],"Psychological harm is common.")
H("750.d.8.B.ii",3,"A crime victim loses work time, pays medical bills and replaces stolen items. These are examples of the:","economic impact of crime on the victim",["no effect","gain","fashion"],"Crime brings financial costs.")
H("750.d.8.B.ii",4,"A victim who withdraws from friends and avoids public places after being attacked is showing a:","social impact of crime on the victim",["economic reward","legal benefit","civil benefit"],"Crime can isolate victims.")
H("750.d.8.C.i",3,"An officer gives a victim a card explaining services and contact numbers for the district attorney's victim services. This is a:","statutory responsibility to inform victims of their rights and services",["private favor","trivial matter","optional gift"],"Law requires officers to provide information.")
H("750.d.8.C.i",4,"The agency that typically assists crime victims with the court process is the:","victim assistance office of the prosecutor",["parks department","school board","public library"],"Prosecutor offices provide victim services.")
H("750.d.8.C.ii",3,"An officer summarizes how a victim can apply for crime victims' compensation to cover medical costs. This is a:","statutory responsibility relating to victims' rights",["unrelated duty","gift","private choice"],"Officers must inform victims of compensation.")
H("750.d.8.C.ii",4,"Crime victims' compensation helps victims by:","paying certain costs such as medical bills or lost wages",["ending the case","punishing the offender","paying lawyers' fees"],"Compensation reimburses certain costs.")
H("750.d.8.C.iii",3,"An officer explains that a victim may give a statement about how a crime affected them before sentencing. This is a:","victim impact statement",["traffic ticket","search warrant","arrest report"],"Victim impact statements describe harm.")
H("750.d.8.C.iii",4,"A victim impact statement allows the court to learn about:","the effects of the crime on the victim",["the officer's pay","the jury's names","the weather"],"The court considers the harm done.")
H("750.d.9.A",3,"A patrol officer finds a 15-year-old skipping school and follows the steps for a status offense, which is conduct that is illegal only because of the person's age. This is:","juvenile law relating to status offenses",["adult sentencing","a felony arrest","a civil suit"],"Status offenses apply to minors.")
H("750.d.9.A",4,"Which is an example of a status offense?","truancy",["burglary","assault","robbery"],"Truancy is illegal only for minors.")
H("750.d.9.B",3,"An officer meets with a juvenile and the parents together to explain the problem and options. This is:","holding a conference with juveniles and parents or guardians",["avoiding parents","an arrest","a trial"],"Conferences involve the family.")
H("750.d.9.B",4,"A purpose of a conference with a juvenile and parents is to:","discuss the behavior and plan for correction",["punish the parents","ignore the child","skip procedure"],"Conferences can resolve minor issues.")
H("750.d.10.A.i",3,"An officer learns that family violence often follows a cycle of tension, an incident and reconciliation. This is understanding the:","dynamics of family violence",["rare event","simple argument only","civil case only"],"Cycles help explain repeated abuse.")
H("750.d.10.A.i",4,"A victim of family violence may stay with an abuser because of:","fear, dependence or hope that the abuse will stop",["no reason at all","enjoying the violence","never being harmed"],"Victims face complex pressures.")
H("750.d.10.A.ii",3,"An officer must know Texas law's definitions of 'family violence' and 'child abuse' to decide whether a crime occurred. These are:","legal issues of family violence and child abuse",["recipes","school rules","parking rules"],"Definitions guide actions.")
H("750.d.10.A.ii",4,"Under Texas law, family violence includes acts that cause or threaten:","physical harm or fear of imminent physical harm within a family or household",["a verbal joke","a missed meal","a lost phone"],"The statute covers harm or threats.")
H("750.d.10.A.iii",3,"A teacher who suspects a child is being abused must make a report to authorities. This is the legal duty of:","mandatory reporting of suspected child abuse",["optional reporting","hiding it","waiting a year"],"Texas law requires reporting.")
H("750.d.10.A.iii",4,"In Texas, a person who suspects child abuse or neglect is required to:","report it to authorities such as DFPS or law enforcement",["wait for proof","tell only a friend","avoid involvement"],"Reporting is required by law.")
H("750.d.10.B.i",3,"Responding to a family violence call, the officer separates the people, checks for injuries and interviews each person apart. This is a recommended step when:","handling family violence calls",["ignoring the call","interviewing together only","leaving"],"Separate interviews protect victims.")
H("750.d.10.B.i",4,"An officer's first step on arriving at a family violence call is to:","ensure safety and check for injuries",["write a report","leave the home","argue with the parties"],"Safety and aid come first.")
H("750.d.10.B.ii",3,"An officer explains to a victim that a court can issue a protective order to keep the abuser away. This is part of handling calls involving:","protective orders in family violence cases",["traffic stops","parking tickets","school visits"],"Protective orders can restrict contact.")
H("750.d.10.B.ii",4,"A protective order in a family violence case generally orders the abuser to:","stay away from the protected person",["move in","pay a fine only","write a letter"],"Protective orders prohibit contact.")
H("750.d.10.B.iii",3,"An officer arrests a person who violates the terms of a protective order and records details for the report. This is:","enforcing protective orders in family violence cases",["ignoring the order","encouraging violation","closing the case"],"Violations can lead to arrest.")
H("750.d.10.B.iii",4,"If an officer finds that a protective order has been violated, the officer may:","make an arrest and document the violation",["ignore it","wait a week","tell the victim to leave"],"Enforcement is part of the process.")
H("750.d.11.A",3,"A cadet studies marijuana, methamphetamine, heroin and prescription opioids as current examples of:","commonly abused drugs in society",["common foods","school supplies","safe medicines in all cases"],"Drug types vary.")
H("750.d.11.A",4,"Which is an example of a commonly abused prescription drug?","opioid pain medication",["vitamin C","aspirin only","multivitamin"],"Opioids are widely misused.")
H("750.d.11.B",3,"A cadet reads the Texas Health and Safety Code to learn which penalty group a drug is in. This is researching:","the effects of substances under Texas law",["school rules","parking rules","tax rules"],"The code classifies controlled substances.")
H("750.d.11.B",4,"The Texas Controlled Substances Act sorts drugs into:","penalty groups based on their potential for harm",["colors","flavors","brands"],"Penalty groups guide charges.")
H("750.d.11.C",3,"An officer finds pills during a search, records where they were found, packages them and logs them as evidence. This follows:","procedures for handling drugs and controlled substances",["no procedures","random handling","tossing it"],"Handling procedures protect the chain of custody.")
H("750.d.11.C",4,"When seizing suspected drugs, an officer must be careful to:","preserve the chain of custody and avoid contamination",["destroy them on the spot","use them","share them"],"Evidence integrity is key.")
H("750.d.12.A",3,"Officers who walk neighborhoods, work with residents and solve problems together are practicing:","community-oriented policing",["avoiding communities","rapid response only","isolated patrol"],"COP builds partnerships.")
H("750.d.12.A",4,"Community-oriented policing emphasizes:","partnerships between police and citizens to solve problems",["only arrests","only reports","isolation"],"Partnership is the core idea.")
H("750.d.12.B",3,"A community-oriented officer needs good communication, patience and problem-solving. These are:","skills needed to be successful in community policing",["unneeded","liabilities","hobbies"],"Skills support partnership.")
H("750.d.12.B",4,"Which skill is most important for a community-oriented police officer?","building rapport and communicating with residents",["avoiding residents","relying on force","working alone"],"Rapport enables cooperation.")
H("750.d.13.A",3,"A police call sheet lists the time of the call, the location and the nature of the incident, while an incident report adds names and details. These are:","components of police reports",["random notes","jokes","no records"],"Reports contain structured information.")
H("750.d.13.A",4,"A supplemental report is written to:","add new information to an earlier report",["replace the first report","hide the first report","delete the case"],"Supplements update the record.")
H("750.d.13.B",3,"Prosecutors, courts and other officers rely on accurate police reports, which is why they are:","important for documenting facts and supporting the case",["unneeded","just paperwork","secret"],"Reports support justice.")
H("750.d.13.B",4,"Why must a police report be accurate and complete?","It may be used in court and in later investigations",["It will be thrown away","Nobody reads it","Accuracy is optional"],"Reports are legal records.")
H("750.d.13.C",3,"During a role-play, a cadet asks a complainant who, what, when, where and how, and writes the answers down. This is:","obtaining the appropriate information for reports",["avoiding questions","ignoring details","guessing"],"Questions gather facts.")
H("750.d.13.C",4,"Which questions help an officer gather the basic facts for a report?","who, what, when, where and how",["why not, maybe, always","wish, hope, guess","paint, draw, color"],"The 5 W's and H cover the basics.")
H("750.d.13.D",3,"A cadet writes a report using correct grammar, proper punctuation and a clear order of events. This is:","writing a police report using proper English",["sloppy writing","slang writing","avoiding writing"],"Clear writing is required.")
H("750.d.13.D",4,"A well-written police report should be:","factual, objective and in correct chronological order",["opinionated","disorganized","vague"],"Reports must be clear.")
H("750.d.14.A",3,"Before stopping a car, an officer considers the location, the time of day and any warning signs about the driver. This is:","applying techniques to assess risk in vehicle stops",["ignoring risk","hurrying","guessing"],"Risk assessment improves safety.")
H("750.d.14.A",4,"One technique to reduce risk when making a vehicle stop is to:","choose a safe, well-lit location when possible",["stop anywhere","stop in traffic","turn off lights"],"Location affects safety.")
H("750.d.14.B",3,"An officer studies the Texas Transportation Code sections on speed limits, stop signs and right of way. This is:","understanding and analyzing traffic laws",["ignoring laws","guessing","avoiding study"],"Officers must know the code.")
H("750.d.14.B",4,"Officers must understand traffic law so that they can:","tell whether a violation has occurred before making a stop",["avoid stops","write random tickets","skip training"],"Knowledge supports lawful stops.")
H("750.d.14.C",3,"In a simulation, an officer follows a seven-step process to contact a driver at a routine traffic stop for a misdemeanor violation. This is a:","simulated misdemeanor traffic stop",["felony takedown","parking check","patrol shift briefing"],"A set process guides routine stops.")
H("750.d.14.C",4,"A routine misdemeanor traffic stop generally ends with:","a citation or warning",["a trial","a prison sentence","a court order"],"Typical outcome: citation or warning.")
H("750.d.14.D",3,"Two patrol units coordinate a high-risk stop of a vehicle linked to a felony, using commands and cover positions. This is a:","simulated felony traffic stop",["routine stop","parking check","traffic count"],"Felony stops use tactics and cover.")
H("750.d.14.D",4,"A felony traffic stop typically uses more officers than a routine stop because:","the risk of a dangerous suspect is higher",["it is cheaper","it is faster","it is required for parking"],"Added risk calls for added resources.")
H("750.d.14.E",3,"An officer clocks a car going 75 in a 55 zone and checks the Transportation Code. This is:","identifying that a traffic law has been violated",["ignoring facts","guessing","avoiding the code"],"Speeding violates the law.")
H("750.d.14.E",4,"To decide whether a traffic offense occurred, an officer compares the driver's action with:","the text of the Texas Transportation Code",["a rumor","a hunch","a menu"],"The code defines offenses.")
H("750.d.14.F",3,"An officer explains to a driver the notice to appear and options for answering a citation. This covers regulations relating to:","arrest, charging procedures, notices and processing of traffic offenses",["no regulation","random procedures","private deals"],"Procedures are set by law.")
H("750.d.14.F",4,"When an officer issues a traffic citation, the driver's signature usually means:","a promise to appear, not an admission of guilt",["a confession","a payment","a trial"],"Signing promises to appear.")
H("750.d.15.A",3,"At a mock crime scene, a cadet dusts a surface with powder and lifts a fingerprint with tape. This is:","lifting and preserving developed latent prints",["destroying prints","ignoring prints","painting"],"Prints are lifted and preserved.")
H("750.d.15.A",4,"After lifting a latent print, the cadet should:","label it with date, location and collector information",["throw it away","leave it unlabeled","wipe the surface"],"Labeling maintains the chain of custody.")
H("750.d.15.B",3,"A cadet photographs a scene from several angles, makes a sketch, collects items and writes notes. This is:","processing a crime scene to photograph, sketch, search, collect and document",["destroying the scene","ignoring the scene","contaminating evidence"],"Scene work includes documenting everything.")
H("750.d.15.B",4,"The first thing officers do to protect a crime scene is to:","secure and limit access to the area",["let everyone in","clean it","move items around"],"Securing prevents contamination.")
H("750.d.16.A",3,"A student studies Texas laws about driving while intoxicated, boating while intoxicated and related offenses. This explains:","laws related to driving while intoxicated and related offenses",["traffic signs only","parking tickets only","vehicle sales"],"DWI laws are part of the Penal Code.")
H("750.d.16.A",4,"Under Texas law, a person is intoxicated if they have a blood alcohol concentration of:","0.08 or more, or lack normal use of mental or physical faculties",["0.00","0.01","0.50 only"],"Texas defines intoxication two ways.")
H("750.d.16.B",3,"An officer sees a car weaving across lanes at night and decides there is reason to stop the driver. This is developing:","reasonable suspicion for an intoxicated driver stop",["no reason","a hunch","a rumor"],"Observable behavior can create reasonable suspicion.")
H("750.d.16.B",4,"Which observation could help establish reasonable suspicion of an intoxicated driver?","weaving, wide turns or erratic speeds",["a clean car","good lane use","stopping at a light"],"Erratic driving is a cue.")
H("750.d.17.A",3,"Officers approach a house by using cover, avoiding silhouettes and communicating quietly. This describes techniques to:","safely approach a residence or building",["rush in","avoid training","ignore dangers"],"Careful approach improves safety.")
H("750.d.17.A",4,"When approaching a building where a suspect may be inside, officers should use:","cover and concealment",["bright lights","loud noise","open ground"],"Cover reduces exposure.")
H("750.d.17.B",3,"Before entering, officers decide who will go first, how they will communicate and how to keep each other covered. This is:","techniques to safely enter and search a building",["random entry","guessing","skipping planning"],"Planning supports safe entry.")
H("750.d.17.B",4,"Teamwork during a building search is important because officers need to:","cover each other and communicate",["work alone","avoid talking","ignore doors"],"Teamwork improves safety.")
H("750.d.17.C",3,"In training, a cadet enters a doorway at an angle, checks corners and clears each part of a room in order. This is:","the correct technique for entering a doorway and searching a room",["unsafe entry","rushing","avoiding rooms"],"Systematic searching reduces risk.")
H("750.d.17.C",4,"When clearing a room, an officer should check:","corners and blind spots in a planned order",["only the center","only the ceiling","only the door"],"Corners hide danger.")
H("750.d.17.D",3,"Officers clear a house room by room, mark cleared areas and watch for hidden persons. These are:","methods for clearing buildings or residences",["methods for parking","methods for cooking","methods for writing"],"Marking cleared rooms prevents duplication.")
H("750.d.17.D",4,"After clearing a room, officers often:","mark it as cleared and move to the next area",["leave it unmarked","go back immediately","lock it"],"Marking keeps track.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_96.jsonl"))
